const item = $input.first().json;
const body = item.body ?? item;
const required = ['assetRequestId', 'prompt', 'negativePrompt', 'dimensions', 'filenameSuggestion', 'altText', 'targetEnv', 'targetWordPress'];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
if (missing.length > 0) {
  throw new Error('Payload invalido, faltan campos: ' + missing.join(', '));
}
if (body.targetEnv !== 'staging') {
  throw new Error('targetEnv debe ser "staging" -- bloqueado por seguridad, nunca produccion.');
}
if (!body.dimensions || typeof body.dimensions.width !== 'number' || typeof body.dimensions.height !== 'number') {
  throw new Error('dimensions.width y dimensions.height son obligatorios y deben ser numeros.');
}
return [{ json: {
  assetRequestId: body.assetRequestId,
  prompt: body.prompt,
  negativePrompt: body.negativePrompt,
  dimensions: body.dimensions,
  filenameSuggestion: body.filenameSuggestion,
  altText: body.altText,
  targetEnv: body.targetEnv,
  targetWordPress: body.targetWordPress,
} }];

const item = $input.first().json;
const raw = (item.filenameSuggestionRaw || 'asset').toString();
const base = raw.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9.]+/g, '-')
  .replace(/^-+|-+$/g, '');
const hasExtension = /\.(jpg|jpeg|png|webp)$/i.test(base);
const finalFilename = hasExtension ? base : base + '.jpg';
return [{ json: { ...item, finalFilename } }];
